style.css:
@-moz-document domain("lixinger.com") {
a{
    color:#4593d0;
}
.text-primary, .primary, .div {
    color: #4593d0 !important;
}
.btn-primary, .badge-primary, .bg-primary, .list-group-item.active,.nav-pills .nav-link.active,.nav-pills .show>.nav-link {
    background-color: #4593d0 !important;
}
.text-danger,.change.up,.high-probability-up,.v-wf-number-color.up {
    color: #e9686b !important;
}
.v-wf-table-fs .table tbody tr td.value.hl .hl.danger,.badge-danger {
    background-color: #e9686b !important;
}
.v-wf-table-fs .table tbody tr td.value.hl .hl{
    background-color: #fdfe67 !important;
}
.wf-stock-info.company table tr.industry, .wf-stock-info.company table tr.indice, .wf-stock-info.company table tr.same-shares {
    background-color:transparent !important;
}
.alert-info{
    background-color:#F0F8FF;
}
.v-wf-question-mark:after {
    content:''
}
.form-control:focus {
    box-shadow: 0 0 0 0.05rem rgba(0, 123, 255, 0.25);
}
.btn-outline-success:focus, .btn-outline-success.focus {
    box-shadow: 0 0 0 0.05rem rgba(40, 167, 69, 0.5);
}
:root {
  --bs-link-color:#4593d0;
  --bs-blue:#4593d0;
  --bs-nav-link-color:#4593d0;
  --bs-info-rgb:69,147,208;
}
}
